import rosterJson from "./roster.json";

// Generated by scripts/build-data.py from the profile CSV + House member pages.
export type AxisKey = "economic" | "social" | "civil" | "democratic";
export type Confidence = "high" | "medium" | "low" | "insufficient";
export type Status = "active" | "deceased" | "expelled" | "changed_office";

export interface Bill {
  id: string;
  title: string;
  date?: string;
  role: "authored" | "coauthored";
  status?: string;
  referral?: string;
  ra?: string;
  informs?: AxisKey;
}

export interface Source { text: string; url: string | null }

export interface Stat {
  score: number | null;
  label: string;
  confidence: Confidence;
  issueCount: number;
  rationale: string;
  sources: Source[];
  billIds: string[];
}

export interface RosterMember {
  slug: string;
  politicianName: string;
  firstName: string;
  lastName: string;
  office: string;
  role: string | null;
  houseCode: string | null;
  party: string | null;
  municipality: string;
  province: string;
  region: string;
  status: Status;
  statusDate: string | null;
  photo: string | null;
  tags: string[];
  profileLabel: string;
  scores: Record<AxisKey, { score: number | null; confidence: Confidence }>;
  authoredCount: number;
  coauthoredCount: number;
}

export interface Member extends RosterMember {
  openCongressId: string;
  openCongressUrl: string;
  houseUrl: string | null;
  assessmentDate: string;
  windowStart: string;
  windowEnd: string;
  summary: string;
  caveat: string;
  stats: Record<AxisKey, Stat>;
  radar: Record<string, number | null>;
  contact: { room: string | null; phones: string[] } | null;
  committees: { name: string; position: string }[];
  bills: Bill[];
}

export const ROSTER = rosterJson as RosterMember[];

const loaders = import.meta.glob<{ default: Member }>("./members/*.json");

export async function loadMember(slug: string): Promise<Member | null> {
  const fn = loaders[`./members/${slug}.json`];
  if (!fn) return null;
  return (await fn()).default;
}

export interface AxisDef {
  key: AxisKey;
  name: string;
  plain: string;
  negPole: string;
  posPole: string;
  negRadar: string;
  posRadar: string;
  negRadarKey: string;
  posRadarKey: string;
  colorVar: string;
  evidence: string;
  houseBand?: [number, number];
  scoredInHouse: number;
}

function band(key: AxisKey): { houseBand?: [number, number]; scoredInHouse: number } {
  const xs = ROSTER.map((m) => m.scores[key].score).filter((v): v is number => v !== null).sort((a, b) => a - b);
  if (xs.length < 20) return { scoredInHouse: xs.length };
  const q = (p: number) => xs[Math.floor((xs.length - 1) * p)]!;
  return { houseBand: [q(0.25), q(0.75)], scoredInHouse: xs.length };
}

// Poles are read from this dictionary — never hard-coded in components.
